export function createHelpUI({e,api,ui,link,filesView,workflow}){
 const staff=()=>ui.actor().role!=='student',labels={open:'Waiting for teacher',answered:'Teacher replied',resolved:'Resolved'},option=(v,t,s)=>'<option value="'+e(v)+'" '+(v===s?'selected':'')+'>'+e(t)+'</option>',hidden=(n,v)=>'<input type="hidden" name="'+n+'" value="'+e(v??'')+'">';
 const tabs=()=>'<nav class="course-progress-tabs" aria-label="Updates and private help">'+link('Updates',{view:'updates'})+link(staff()?'Help requests':'My help requests',{view:'help'}).replace('<a ','<a aria-current="page" ')+'</nav>';
 async function assignmentPanel(a,studentId){if(a.status!=='published')return '';try{const d=await api('help-thread?'+new URLSearchParams({assignmentId:a.id,...(staff()?{studentId}:{})}));return '<div class="help-assignment-bar"><span><strong>Private help</strong> <small>'+e(d.thread?labels[d.thread.status]:staff()?'No questions from this student yet.':'Ask your teacher about this task.')+'</small></span><button type="button" class="btn" data-open-help="'+e(a.id)+'" data-help-student="'+e(d.student.id)+'">'+(staff()?'Open conversation':'Ask for help')+' →</button></div>';}catch(error){return '<p class="muted">Private help is unavailable: '+e(error.message)+'</p>';}}
 async function list(params){const status=params.get('status')??(staff()?'open':''),q=new URLSearchParams({status});for(const k of ['classId','search','offset'])if(params.get(k))q.set(k,params.get(k));const d=await api('help-list?'+q),route={view:'help',status,...(params.get('classId')?{classId:params.get('classId')}:{}),...(params.get('search')?{search:params.get('search')}:{})};return tabs()+'<div class="learning-section-title"><h2>'+ (staff()?'Private help requests':'My private help requests')+'</h2><button type="button" class="btn" data-help-refresh>Refresh</button></div><div class="learning-stats"><div><strong>'+d.summary.open+'</strong><span>Waiting for teacher</span></div><div><strong>'+d.summary.answered+'</strong><span>Teacher replied</span></div><div><strong>'+d.summary.resolved+'</strong><span>Resolved</span></div></div><form id="help-filters" class="community-filters"><label>Status <select name="status">'+[['','All requests'],['open','Waiting for teacher'],['answered','Teacher replied'],['resolved','Resolved']].map(([v,t])=>option(v,t,status)).join('')+'</select></label><label>Class <select name="classId">'+option('','All my classes',params.get('classId')||'')+d.classes.map(c=>option(c.id,c.name,params.get('classId'))).join('')+'</select></label><label>Find <input name="search" value="'+e(params.get('search')||'')+'" maxlength="120" placeholder="Task or student name"></label></form><p class="muted">'+d.total+' matching requests. Private to the student and authorised school staff.</p><div class="updates-list">'+d.items.map((r,i)=>(i===6?'<details class="updates-more"><summary>Show '+(d.items.length-6)+' more on this page</summary><div class="updates-list">':'')+'<article class="vle-panel update-row"><div class="update-copy"><span class="learning-tag">'+e(labels[r.status])+'</span><h3>'+link(r.title,{help:r.assignmentId,...(staff()?{studentId:r.studentId}:{})})+'</h3><small>'+e(r.className)+(staff()?' · '+e(r.studentName):'')+' · '+r.messages+' messages</small></div>'+link('Open conversation →',{help:r.assignmentId,...(staff()?{studentId:r.studentId}:{})})+'</article>'+((i===d.items.length-1&&d.items.length>6)?'</div></details>':'')).join('')+(!d.items.length?'<p class="learning-empty">No requests match these filters. '+(staff()?'Students can ask for help from an assignment page.':link('Open a classroom to choose a task',{view:'classes'}))+'</p>':'')+'</div><nav class="updates-pagination" aria-label="Help request pages">'+(d.offset?link('← Previous requests',{...route,offset:Math.max(0,d.offset-20)}):'')+(d.offset+20<d.total?link('More requests →',{...route,offset:d.offset+20}):'')+'</nav>';}
 async function thread(params){const d=await api('help-thread?'+new URLSearchParams({assignmentId:params.get('help'),...(params.get('studentId')?{studentId:params.get('studentId')}:{})})),h=d.thread,messages=h?.messages||[],message=m=>'<article class="help-message '+(m.teacher?'help-teacher':'')+'"><div class="learning-section-title"><strong>'+e(m.authorName)+(m.teacher?' · Teacher':'')+'</strong><small>'+e(new Date(m.createdAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'}))+'</small></div><p class="vle-prose">'+e(m.body)+'</p>'+(m.files||[]).filter(f=>f.mime?.startsWith('image/')).map(f=>'<img class="community-evidence" src="data:'+e(f.mime)+';base64,'+e(f.data)+'" alt="'+e(f.name)+'">').join('')+filesView(m.files)+'</article>';
  return tabs()+'<div class="learning-section-title"><p>'+link('← Back to assignment',{class:d.assignment.classId,assignment:d.assignment.id,...(staff()?{review:d.student.id}:{})})+' · '+link('All help requests',{view:'help',status:''})+'</p><button type="button" class="btn" data-help-refresh>Refresh</button></div><div class="learning-section-title"><h2>Private help · '+e(d.assignment.title)+'</h2><span class="learning-tag">'+e(h?labels[h.status]:'New question')+'</span></div>'+(h?.status==='resolved'?'<p class="muted">You can reopen this request or send another message if you still need help.</p>':'')+'<p>'+e(d.student.name)+' ↔ '+e(d.teacher.name)+' · '+e(d.assignment.className)+'</p><p class="vle-note">Private to this student and authorised school staff. This conversation does not change marks or submit assignment work.</p><div class="help-messages">'+(messages.length>6?'<details class="vle-panel"><summary>Show '+(messages.length-6)+' earlier messages</summary>'+messages.slice(0,-6).map(message).join('')+'</details>':'')+messages.slice(-6).map(message).join('')+'</div>'+(d.canSend?'<form data-vle="help-message" class="vle-panel">'+hidden('assignmentId',d.assignment.id)+hidden('studentId',d.student.id)+hidden('expectedRevision',h?.revision||0)+'<label class="vle-field">'+(staff()?'Your reply':'My question or reply')+'<textarea name="body" maxlength="4000" placeholder="Explain where you are stuck or write your reply."></textarea></label><label class="vle-field">Attach evidence · up to 2 × 1 MB<input type="file" name="uploads" multiple accept=".pdf,.txt,.png,.jpg,.jpeg,.webp,.docx"></label><div class="vle-actions"><button type="button" class="text-button" data-help-clear>Clear unsent draft</button><button type="submit" name="intent" value="send" class="btn primary">'+(staff()?'Send reply':'Send to teacher')+'</button>'+(staff()?'<button type="submit" name="intent" value="resolve" class="btn">Reply & resolve</button>':'')+'</div><small>Your message is added to this private conversation when you send it.</small></form>':'<p class="learning-empty">This student has not requested help on this task yet.</p>')+(h?'<div class="vle-actions"><button type="button" class="btn" data-help-status data-assignment="'+e(d.assignment.id)+'" data-student="'+e(d.student.id)+'" data-revision="'+h.revision+'" data-resolved="'+(h.status!=='resolved')+'">'+(h.status==='resolved'?'Reopen request':'Mark resolved')+'</button></div>':'');
 }
 function bind(root){root.querySelectorAll('[data-open-help]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{if(!await workflow.flushForHelp(root))return;location.hash='/classroom?'+new URLSearchParams({help:b.dataset.openHelp,...(staff()?{studentId:b.dataset.helpStudent}:{})});}catch(error){ui.toast('Your work has not been saved: '+error.message);}finally{if(b.isConnected)b.disabled=false;}}));const navigate=f=>location.hash='/classroom?'+new URLSearchParams({view:'help',...Object.fromEntries(new FormData(f))});root.querySelector('#help-filters')?.addEventListener('change',ev=>navigate(ev.currentTarget));root.querySelector('#help-filters')?.addEventListener('submit',ev=>{ev.preventDefault();navigate(ev.currentTarget);});root.querySelector('[data-help-clear]')?.addEventListener('click',ev=>{ev.currentTarget.closest('form').reset();ui.dirty(false);});root.querySelector('[data-help-refresh]')?.addEventListener('click',()=>{if(ui.isDirty?.()){ui.toast('Send or clear your unsent draft before refreshing.');return;}ui.render();});root.querySelector('[data-help-status]')?.addEventListener('click',async ev=>{if(ui.isDirty?.()){ui.toast('Send or clear your unsent draft before changing the request status.');return;}const b=ev.currentTarget;b.disabled=true;try{await api('help-status',{assignmentId:b.dataset.assignment,studentId:b.dataset.student,expectedRevision:Number(b.dataset.revision),resolved:b.dataset.resolved==='true'});ui.render();}catch(error){ui.toast(error.message);b.disabled=false;}});}
 function readAction(action,data,intent){if(action==='help-message')data.resolve=intent==='resolve';}
 return{assignmentPanel,list,thread,bind,readAction};
}
